"""Independent exact-package audit; reads only, writes critic-owned evidence."""
from pathlib import Path, PurePosixPath
from collections import defaultdict
from io import BytesIO
from urllib.parse import urlparse, unquote
import hashlib, json, re, datetime
from PIL import Image

TASK = Path(__file__).resolve().parent
REPO = TASK / "archive-repo"
PREFIX = "Docs/Design/StructureReferences/2026-11-25"
PKG = REPO / PREFIX
EXPECTED_MANIFEST = "fa2f08a709128765b24d8b37cb37f953fb66d23eef207f4057675dca2fdd4db9"
EXPECTED_TREE = "ea7a18080b1bd081710624ffc93e80d397728a03"
BASE_COMMIT = "b80c61f13ba31bb0940792dd47976a8e2878dbf5"
BASE_TREE = "598ca77bd0635e418e7eced4db6384658f9687d4"
REQUIREMENTS = "c10ab73c075116d486afd2c7eca3390ddf1e4435c3d2699bfc1ed40b4efa137a"
FREEZE = "2763fb34296c4eff3c74fa7343875aa3af304922f11ac06f3ae70820b4520fdb"
VISUAL = "2bd90f4965b1a2a83ad0d3094f5f804ba41956b74a573dbfbf7a1dc22f88b37b"

def sha(data):
    return hashlib.sha256(data).hexdigest()
def oid(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()
def read_json(path):
    return json.loads(path.read_bytes())
def required(condition, text):
    if not condition:
        raise AssertionError(text)
def git_tree(rows):
    directories = defaultdict(dict)
    for row in rows:
        parts = row["path"].split("/")
        for i in range(len(parts)-1):
            directories["/".join(parts[:i])][parts[i]] = ("40000", "/".join(parts[:i+1]))
        directories["/".join(parts[:-1])][parts[-1]] = (row["mode"].lstrip("0"), row["sha"])
    def build(path):
        body = bytearray()
        entries = directories[path]
        order = sorted(entries, key=lambda n: (n + ("/" if entries[n][0] == "40000" else "")).encode())
        for name in order:
            mode, value = entries[name]
            target = build(value) if mode == "40000" else value
            body += mode.encode() + b" " + name.encode() + b"\0" + bytes.fromhex(target)
        return hashlib.sha1(b"tree " + str(len(body)).encode() + b"\0" + body).hexdigest()
    return build("")
def path_for(locator):
    p = REPO / locator if locator.startswith(PREFIX + "/") else PKG / locator
    required(p.resolve().is_relative_to(PKG.resolve()), "Archive target escapes package: " + locator)
    return p
def verify_archive(locator, expected_sha=None, expected_blob=None, expected_bytes=None):
    p = path_for(locator)
    required(p.is_file(), "Missing archive target: " + locator)
    data = p.read_bytes()
    if expected_sha is not None:
        required(sha(data) == expected_sha, "SHA mismatch: " + locator)
    if expected_blob is not None:
        required(oid(data) == expected_blob, "Git blob mismatch: " + locator)
    if expected_bytes is not None:
        required(len(data) == expected_bytes, "Byte-count mismatch: " + locator)
    return data

checks = []
def run(name, fn):
    try:
        detail = fn()
        checks.append({"name": name, "status": "PASS", "detail": detail})
    except Exception as exc:
        checks.append({"name": name, "status": "FAIL", "error": str(exc)})

manifest_path = TASK / "archive-expected-paths.json"
manifest_bytes = manifest_path.read_bytes()
manifest = json.loads(manifest_bytes)
baseline_commit = read_json(TASK / "critic-base-commit-fresh-readback.json")["readback"]
baseline_full = read_json(TASK / "critic-base-tree-fresh-readback.json")["readback"]
baseline = [r for r in baseline_full["tree"] if r["type"] != "tree"]
base_map = {r["path"]: r for r in baseline}
freeze = read_json(PKG / "final-freeze.json")
visual = read_json(PKG / "reviews/critic-final-visual-acceptance.json")
resolver = read_json(PKG / "review-input-resolver.json")
images = read_json(PKG / "image-index.json")["images"]
image_map = {r["id"]: r for r in images}
selections = read_json(PKG / "selected-status.json")["selections"]

def identity_check():
    required(sha(manifest_bytes) == EXPECTED_MANIFEST, "Unexpected manifest snapshot")
    required(manifest["candidate_tree"] == EXPECTED_TREE, "Unexpected candidate tree")
    required(baseline_commit["sha"] == BASE_COMMIT and baseline_commit["tree"]["sha"] == BASE_TREE, "Fresh base commit differs")
    required(baseline_full["sha"] == BASE_TREE and baseline_full["truncated"] is False, "Incomplete fresh base tree")
    required(len(baseline) == 4144 and len(base_map) == 4144, "Baseline leaf count")
    required(git_tree(baseline) == BASE_TREE, "Fresh baseline tree reconstruction failed")
    return {"fresh_baseline_leaves": len(baseline), "base_tree": BASE_TREE, "manifest_sha256": sha(manifest_bytes)}
run("independent_fresh_baseline_and_manifest_identity", identity_check)

def package_inventory():
    indexed = {r["path"]: r for r in manifest["files"]}
    required(len(indexed) == len(manifest["files"]) == 295, "Expected295 unique new paths")
    disk = {str(p.relative_to(REPO)):p for p in REPO.rglob("*") if p.is_file()}
    required(set(disk) == set(indexed), "Disk/manifest path set differs")
    all_rows = []
    image_files = 0
    for name, p in disk.items():
        row = indexed[name]; data = p.read_bytes()
        required(name.startswith(PREFIX + "/") and name not in base_map, "Outside-prefix or preexisting path: " + name)
        required(not p.is_symlink(), "New symlink")
        required(row["mode"] == "100644" and row["type"] == "blob", "Unexpected new mode/type")
        required(sha(data) == row["sha256"] and oid(data) == row["git_blob_sha"] and len(data) == row["bytes"], "File metrics: " + name)
        if p.suffix.lower() in {".png", ".jpg", ".jpeg"}:
            required(not data.startswith(b"version https://git-lfs.github.com/spec/"), "Image is LFS pointer")
            with Image.open(BytesIO(data)) as im:
                im.verify()
            image_files += 1
        else:
            data.decode("utf-8")
        all_rows.append({"path":name,"mode":row["mode"],"type":"blob","sha":row["git_blob_sha"]})
    tree = git_tree(baseline + all_rows)
    required(tree == EXPECTED_TREE, "Independent candidate tree differs")
    required(not any(r["path"].startswith(".github/") for r in all_rows), "Operational workflow change")
    return {"new_paths":len(indexed),"valid_image_files":image_files,"tree":tree,"baseline_files_unchanged":4144}
run("every_file_byte_mode_and_additive_tree", package_inventory)

def freeze_check():
    for path, expected in [("requirements.json",REQUIREMENTS),("final-freeze.json",FREEZE),("reviews/critic-final-visual-acceptance.json",VISUAL)]:
        required(sha((PKG/path).read_bytes()) == expected, "Frozen doc mismatch: " + path)
    for row in freeze["generation_index_bindings"]:
        data = (TASK / row["path"]).read_bytes()
        required(sha(data) == row["sha256"], "Frozen index changed")
        paths = resolver["sha256_to_archive_paths"].get(row["sha256"],[])
        required(paths, "Frozen index has no archive locator")
        for locator in paths:
            verify_archive(locator,row["sha256"])
    required(freeze["selected_count"] == 9 and freeze["generated_original_count"] == 17 and freeze["generation_frozen"], "Freeze counts/state")
    required(visual["status"] == "VISUAL_PASS_DELIVERY_PENDING" and visual["all_mandatory_visual_checks_passed"], "Visual scope state")
    return {"frozen_indexes":4,"frozen_creative_documents":3,"selected":9,"originals":17}
run("frozen_creative_documents_and_indexes", freeze_check)

def original_checks():
    native_rows = {}
    for source_index in ["generation-index.json","counter-builder/generation-index.json"]:
        doc = read_json(TASK/source_index)
        for row in doc.get("images",doc.get("generations",[])):
            native_rows[row.get("id",row.get("generation_id"))] = row
    required(len(native_rows) == len(images) == 17, "Original count mismatch")
    for row in images:
        data = verify_archive(row["path"],row["sha256"],row["git_blob_sha"],row["bytes"])
        required(data[:8] == b"\x89PNG\r\n\x1a\n", "Original not actual PNG")
        with Image.open(BytesIO(data)) as im:
            required(list(im.size) == row["dimensions"], "Original dimensions mismatch")
        native = native_rows[row["id"]]
        source = Path(native.get("source_file",native.get("native_original_path","")))
        required(source.is_file() and source.read_bytes() == data, "Not identical to actual native generation output")
        prompt = verify_archive(row["prompt"],row["prompt_sha256"],row["prompt_git_blob_sha"],row["prompt_bytes"])
        for review in row["review_entries"]:
            rr = json.loads(verify_archive(review["path"],review["sha256"]))
            required(rr["image_sha256"] == row["sha256"], "Review bound to wrong original")
    return {"native_originals_identical":17,"exact_prompts":17,"reviewed_attempts":17,"no_pointer_originals":True}
run("all_original_images_prompts_and_attempt_reviews", original_checks)

def selected_check():
    final_by_series = {r["series_id"]:r for r in visual["selected"]}
    required(len(selections) == len(final_by_series) == 9, "Selection count")
    for row in selections:
        review = final_by_series[row["series_id"]]
        required(row["id"] == review["image_id"] and row["sha256"] == review["sha256"], "Selected identity mismatch")
        alias = verify_archive(row["path"],row["sha256"],row["git_blob_sha"],row["bytes"])
        original = verify_archive(row["original"],row["sha256"],row["git_blob_sha"],row["bytes"])
        required(alias == original, "Selected alias changes bytes")
        raw = verify_archive(row["review"],row["review_sha256"])
        required(sha(raw) == review["per_sheet_review_sha256"], "Selection review differs from visual freeze")
        rr = json.loads(raw)
        required(rr["status"] in {"PASS","PASS_ANCHOR"} and rr["score"] >= 9.5 and all(v == "PASS" for v in rr["checks"].values()), "Selected visual check failed")
        with Image.open(BytesIO(alias)) as im:
            required(list(im.size) == review["native_size"], "Selected native size differs")
    return {"same_blob_aliases":9,"mandatory_per_sheet_checks":"all pass","rotation_views":24}
run("nine_selected_aliases_and_independent_review_bindings", selected_check)

def invocation_check():
    links = read_json(PKG/"reference-links.json")
    required(not links["invocations_without_registered_output"] and len(links["generation_inputs"]) == 17, "Unbound invocations")
    total_inputs = 0
    for row in links["generation_inputs"]:
        out = image_map[row["id"]]
        required(row["output_sha256"] == out["sha256"] and row["prompt_sha256"] == out["prompt_sha256"], "Invocation image/prompt differs")
        snapshots = row["exact_invocation_index_snapshots"]
        required(snapshots, "No exact invocation snapshot")
        idx = json.loads(verify_archive(snapshots[0],row["exact_invocation_index_sha256"]))
        inv = next(x for x in idx["invocations"] if x.get("id",x.get("invocation_id")) == row["id"])
        required(inv["prompt_sha256"] == row["prompt_sha256"], "Exact invocation prompt hash differs")
        if "prompt" in inv:
            required(inv["prompt"].encode() == verify_archive(out["prompt"]), "Literal invoked prompt differs")
        if "ordered_reference_inputs" in inv:
            expected = [(x["local_path"],x["sha256"]) for x in inv["ordered_reference_inputs"]]
        else:
            expected = list(zip(inv["referenced_image_paths"],inv["reference_sha256"]))
        got = [(x["original_locator"],x["sha256"]) for x in row["actual_inputs_in_order"]]
        required(expected == got, "Actual input order changed")
        for i, item in enumerate(row["actual_inputs_in_order"],1):
            required(item["order"] == i and item["archive_paths"], "Missing ordered input")
            for target in item["archive_paths"]:
                verify_archive(target,item["sha256"],item["git_blob_sha"],item["bytes"])
            total_inputs += 1
    return {"invocations":17,"exact_ordered_input_occurrences":total_inputs}
run("exact_invoked_prompts_and_ordered_reference_inputs", invocation_check)

def provenance_check():
    docs = read_json(PKG/"document-provenance.json")["documents"]
    for row in docs:
        verify_archive(row["archive_path"],row["sha256"],row["git_blob_sha"],row["bytes"])
    for digest, locators in resolver["sha256_to_archive_paths"].items():
        required(locators, "Empty hash target")
        for locator in locators:
            verify_archive(locator,digest)
    for _, locators in resolver["original_locator_to_archive_paths"].items():
        for locator in locators:
            verify_archive(locator)
    guide = TASK.parent / "havenline-character-style-360/CHARACTER_STYLE_REFERENCE.md"
    digest = sha(guide.read_bytes())
    required(digest == "32be92026eb2f454f97c253fb32e0bbe79ffa15ad4eb3ec1b30086df18e3bcba", "Unexpected guide bytes")
    required(digest in resolver["sha256_to_archive_paths"], "Actually-read context guide unresolved")
    required(str(guide) in resolver["original_locator_to_archive_paths"], "Guide original locator absent")
    for digest, urls in resolver["sha256_to_immutable_existing_repository_urls"].items():
        for url in urls:
            marker = "/blob/" + BASE_COMMIT + "/"
            required(marker in url, "Existing source URL not immutable baseline")
            path = unquote(url.split(marker,1)[1])
            required(path in base_map, "Existing source missing from fresh baseline")
            candidates = [p for p in (TASK/"counter-builder/source-recovery").glob("*") if p.is_file() and sha(p.read_bytes()) == digest]
            if digest == sha(guide.read_bytes()):
                candidates.append(guide)
            required(candidates, "No exact local bytes for existing source")
            required(any(oid(p.read_bytes()) == base_map[path]["sha"] for p in candidates), "Existing source bytes do not match fresh baseline Git identity")
    return {"exact_document_records":len(docs),"hash_resolver_entries":len(resolver["sha256_to_archive_paths"]),"locator_entries":len(resolver["original_locator_to_archive_paths"]),"context_guide_repair":"resolved","immutable_existing_sources":len(resolver["sha256_to_immutable_existing_repository_urls"])}
run("document_provenance_and_all_hash_locator_targets", provenance_check)

def crop_check():
    qa = read_json(PKG/"review-evidence/index.json")
    required(qa["qa_image_files"] == 68 and qa["qa_provenance_files"] == 24, "QA counts differ")
    for row in qa["files"]:
        verify_archive(row["archive_path"],row["sha256"],row["git_blob_sha"],row["bytes"])
    count = 0
    for row in visual["attempt_review_bindings"]:
        rr = json.loads(verify_archive(row["path"],row["sha256"]))
        for crop in rr["crop_evidence"]:
            targets = resolver["sha256_to_archive_paths"].get(crop["sha256"],[])
            required(targets, "Crop evidence hash not resolved")
            for target in targets:
                verify_archive(target,crop["sha256"])
            count += 1
        targets = resolver["sha256_to_archive_paths"].get(rr["crop_provenance_sha256"],[])
        required(targets, "Exact crop provenance version absent")
        for target in targets:
            verify_archive(target,rr["crop_provenance_sha256"])
    return {"qa_images":68,"qa_provenance_or_observations":24,"review_crop_references_checked":count,"attempt_reviews":17}
run("every_native_review_crop_and_provenance_version", crop_check)

def navigation_check():
    links = set()
    for name in ["README.md","GALLERY.md"]:
        text = (PKG/name).read_text()
        for target in re.findall(r"\]\(([^)]+)\)",text):
            if target.startswith(("https://","http://","#")):
                continue
            target = target.split("#",1)[0]
            required((PKG/target).exists(), "Broken navigation link: " + target)
            links.add(target)
    gallery = (PKG/"GALLERY.md").read_text()
    required(gallery.count("[![") == 9, "Gallery does not have9 rendered previews")
    for row in selections:
        required(row["path"] in gallery, "Selected sheet absent from gallery")
    readme = (PKG/"README.md").read_text()
    required("1254 × 1254" in readme and "1536 × 1024" in readme, "Native dimensions not honest")
    required("two distinct usable bidirectional camp openings" in readme and "static raster references" in readme, "Static/runtime boundary missing")
    return {"unique_relative_navigation_targets":len(links),"preview_cells":9,"scope_and_native_size_statements":"verified"}
run("gallery_navigation_and_delivery_claims", navigation_check)

def unknown_review_hashes():
    known = set(resolver["sha256_to_archive_paths"]) | set(resolver["sha256_to_immutable_existing_repository_urls"])
    known |= {sha(p.read_bytes()) for p in PKG.rglob("*") if p.is_file()}
    unknown = defaultdict(list)
    def walk(value, trail, origin):
        if isinstance(value,dict):
            for k,v in value.items():walk(v,trail+[k],origin)
        elif isinstance(value,list):
            for i,v in enumerate(value):walk(v,trail+[str(i)],origin)
        elif isinstance(value,str) and re.fullmatch("[0-9a-f]{64}",value) and value not in known:
            unknown[value].append({"path":origin,"field":".".join(trail)})
    for p in PKG.rglob("*.json"):
        walk(read_json(p),[],str(p.relative_to(PKG)))
    historical_videos = {"62f7cfe644de3826cfdd6d91bc23c0ab8d9e4fde3e175c90f762e604547bb0ca","4c9051cbea6df0efa3e7288b13b6d17da46e857274869b0b43d2f96ff6cc79d2"}
    required(set(unknown) == historical_videos, "Other unresolved SHA256 references remain")
    return {"unresolved_actual_image_prompt_review_inputs":0,"historical_source_video_hashes_only":dict(unknown),"boundary":"These source-video provenance values are historical context, not generated artwork or actual imagegen inputs. All inspected stills are retained or bound to immutable baseline files."}
run("complete_sha256_reference_scan", unknown_review_hashes)

report = {"schema_version":1,"reviewer":"structure_critic independent agent","recorded_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"candidate_tree":manifest["candidate_tree"],"manifest_sha256":sha(manifest_bytes),"base_commit":BASE_COMMIT,"base_tree":BASE_TREE,"freeze_sha256":FREEZE,"visual_review_sha256":VISUAL,"checks":checks,"passed_checks":sum(x["status"]=="PASS" for x in checks),"required_checks":len(checks),"status":"PASS" if all(x["status"]=="PASS" for x in checks) else "FAIL","remote_ref_checked":False,"scope":"Concrete local frozen package audit; remote delivery remains pending."}
out = TASK/"critic-package-audit-data.json"
out.write_text(json.dumps(report,indent=2)+"\n")
print(json.dumps({"status":report["status"],"passed":report["passed_checks"],"required":report["required_checks"],"candidate_tree":report["candidate_tree"],"failed":[x for x in checks if x["status"]=="FAIL"]},indent=2))
